<script lang="ts">
 import {onDestroy} from 'svelte';import {creditList,type ChapterCredit} from './native-team-client';import {publicUuid,record} from './validation';
 let {chapterId}:{chapterId:string}=$props();let rows=$state<ChapterCredit[]>([]);let epoch=0,abort:AbortController|undefined;
 onDestroy(()=>{epoch++;abort?.abort();});
 $effect(()=>{const id=chapterId,token=++epoch;abort?.abort();const controller=new AbortController();abort=controller;rows=[];void(async()=>{try{const response=await fetch(`/api/v1/chapter/${publicUuid(id)}/credits`,{credentials:'omit',redirect:'error',cache:'no-store',signal:controller.signal});if(response.status!==200||!response.headers.get('content-type')?.startsWith('application/json')){await response.body?.cancel();return;}const reader=response.body?.getReader();if(!reader)return;let total=0;const chunks:Uint8Array[]=[];try{for(;;){const part=await reader.read();if(part.done)break;total+=part.value.byteLength;if(total>16000){await reader.cancel();return;}chunks.push(part.value);}}finally{reader.releaseLock();}const bytes=new Uint8Array(total);let offset=0;for(const part of chunks){bytes.set(part,offset);offset+=part.length;}const body=record(JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes)));if(token===epoch&&body.result==='ok'&&body.scope==='instance-local-public-attribution')rows=creditList(body.credits);}catch{/* Credits never block reading. */}})();return()=>controller.abort();});
</script>
{#if rows.length}<section class="space-y-2" aria-label="Chapter credits"><h3 class="font-medium">Chapter credits</h3><p class="text-sm">Attribution on this site</p><ul>{#each rows as row}<li>{row.role==='translator'?'Translator':row.role==='editor'?'Editor':'Typesetter'}: {row.name}</li>{/each}</ul></section>{/if}
